import{d as p,C as a,o as g,c as d,a3 as s,E as e,j as n,a as h}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"正易心法·第十二章","description":"《正易心法》第十二章——健顺动入，陷丽止说：八字不是八卦的专属标签，而是卦画结构的通用描述原则；以阖户（姤初）、辟户（复初）示范精确到爻。","frontmatter":{"title":"正易心法·第十二章","description":"《正易心法》第十二章——健顺动入，陷丽止说：八字不是八卦的专属标签，而是卦画结构的通用描述原则；以阖户（姤初）、辟户（复初）示范精确到爻。","category":"guide","aliases":["正易心法第十二章","健顺动入陷丽止说","八字非专属"],"source":["《正易心法》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/zheng-yi-xin-fa/chapter-12.md","filePath":"yijing/zheng-yi-xin-fa/chapter-12.md","lastUpdated":1790647676000}'),c={name:"yijing/zheng-yi-xin-fa/chapter-12.md"},x=p({...c,setup(u){const o=[{id:"z12-01",label:"一、非特乾坤六子",showLabel:!0,sentences:[["健顺动入，陷丽止说。非特乾坤，六子",{text:"训释",glossary:"xunshi"},"。"]],note:["健、顺、动、入、陷、丽、止、说——这八个字不只是乾坤与六子的训释标签。（若只是八个标签，背下来就够了；麻衣要说的是：它们是**卦画结构的描述原则**。这一字之差，就是「只作八字说」（第四章）与「当求之于画象」的分野。）"]},{id:"z12-02",label:"二、不可专于八字",showLabel:!0,sentences:[["非特训释，盖谓不可专于八字上取也，当求之于画象。"]],note:["说「非特训释」，是说不可以只在这八个字上死板套用，应当从卦画中求取真义。（**从名词到动词的转变**：不是「乾叫做健」，而是「三画皆奇的结构，就是健的运作方式」——凡见三画皆奇，就知道有「健」象，不只是乾卦。）"]},{id:"z12-03",label:"三、八字的卦画定义",showLabel:!0,sentences:[["健谓三画奇也，顺谓三画纯偶是也，动谓一阳在二阴下是，入谓一阴在二阳下是，陷谓一阳在二阴中是，丽谓一阴在二阳中是，止则一阳在二阴之上是，说则一阴在二阳上是。"]],note:["健，是三爻皆奇（阳）；顺，是三爻皆偶（阴）；动，是一阳在二阴之下；入，是一阴在二阳之下；陷，是一阳在二阴之中；丽，是一阴在二阳之中；止，是一阳在二阴之上；说，是一阴在二阳之上。（规律很清楚：**异类爻在下 → 动／入；在中 → 陷／丽；在上 → 止／说**。位置本身就是意义——每一个定义都精确对应了卦画的**动态结构**，而不只是静态标签。例如坤「顺」是静态的承载，巽「入」却多了方向感：阴气从下方渗入阳气之中——这是风的运动，不是地的运动。）"]},{id:"z12-04",label:"四、多见于画象",showLabel:!0,sentences:[["凡此所论，多见于画象。"]],note:["凡此所论，都要从卦画之象中去看。（这是本章最重要的跃升：**八字可推广到六十四卦**——凡卦画中出现相同结构，就有相同的义理。不是「震＝动」这个等式，而是「一阳在二阴下＝动」这个结构原则，适用于所有含此结构的卦与爻。）"]},{id:"z12-05",label:"五、阖户与辟户",showLabel:!0,sentences:[["如",{text:"阖户",glossary:"hehu"},"谓之坤，则",{text:"姤",glossary:"gou"},"之初爻是；",{text:"辟户",glossary:"pihu"},"谓之乾，则",{text:"复",glossary:"fu"},"之初爻是。"]],note:["比如「阖户谓之坤」——姤卦的初爻（一阴生于下）就是这个象；「辟户谓之乾」——复卦的初爻（一阳生于下）就是这个象。（这是本章最精彩的一步：《系辞传》说「阖户谓之坤，辟户谓之乾」，讲的是**状态**（坤、乾整卦）；麻衣回到卦画，找到了更精确的**过程**——阴气刚刚闭合的那一刻是姤初爻，阳气刚刚开启的那一刻是复初爻。**过程比状态更有信息量**，这正是第六章「辞外见意」的具体实践：先找《系辞》的一个命题，不满足于文字理解，回到卦画找最精确的对应。）"]}],r=[{id:"xunshi",term:"训释",pinyin:"xùn shì",meaning:"训诂解释。指文字层面的义理概括。"},{id:"hehu",term:"阖户",pinyin:"hé hù",meaning:"关闭门户。坤象，阴气闭合。麻衣指姤之初爻——阴气刚刚闭合的那一刻。"},{id:"pihu",term:"辟户",pinyin:"pì hù",meaning:"开启门户。乾象，阳气开启。麻衣指复之初爻——阳气刚刚开启的那一刻。"},{id:"gou",term:"姤",pinyin:"gòu",meaning:"姤卦（上乾下巽），一阴生于下，夏至一阴生。此处取其初爻为「阖户」之象。"},{id:"fu",term:"复",pinyin:"fù",meaning:"复卦（上坤下震），一阳生于下，冬至一阳来复。此处取其初爻为「辟户」之象。"}];return(b,t)=>{const i=a("DaoTextReading"),l=a("DaoKeywordCards");return g(),d("div",null,[t[0]||(t[0]=s(`<h1 id="正易心法·第十二章" tabindex="-1">正易心法·第十二章 <a class="header-anchor" href="#正易心法·第十二章" aria-label="Permalink to &quot;正易心法·第十二章&quot;">​</a></h1><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>本章是第八章「纵横施设」的<strong>方法论深化</strong>，核心命题是：</p><blockquote><p><strong>八卦的八个义理标签（健顺动入陷丽止说），不是八卦的专属名称，而是卦画结构的通用描述原则——凡六十四卦中出现相同结构，就适用相同的义理。</strong></p></blockquote><p>这是一个<strong>从特殊到普遍</strong>的方法论跃升：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>传统（特殊）：震 = 动（专属标签，只用于震卦）</span></span>
<span class="line"><span>麻衣（普遍）：「一阳在二阴下」= 动（结构原则，适用于所有含此结构的卦／爻）</span></span>
<span class="line"><span>              复卦初爻 = 一阳在二阴下 → 有「动」象</span></span>
<span class="line"><span>              任何重卦的下卦若为震 → 有「动」象</span></span></code></pre></div><h2 id="为什么重要" tabindex="-1">为什么重要 <a class="header-anchor" href="#为什么重要" aria-label="Permalink to &quot;为什么重要&quot;">​</a></h2><p><strong>这是对第四章「只作八字说」的正面回应</strong>：</p><table tabindex="0"><thead><tr><th></th><th>做法</th><th>结果</th></tr></thead><tbody><tr><td><strong>错误（汉儒）</strong></td><td>乾＝健，背下来，用到乾就说「健」</td><td>把八字当成标签贴纸</td></tr><tr><td><strong>正确（麻衣）</strong></td><td>「健」= 三画皆奇的卦画结构；凡见三画皆奇，就有「健」象</td><td>从名词到动词的转变</td></tr></tbody></table><p><strong>八字的卦画定义</strong>（注意结构的规律）：</p><table tabindex="0"><thead><tr><th>位置</th><th>坤系（阳入坤）</th><th>乾系（阴入乾）</th></tr></thead><tbody><tr><td>异类爻在<strong>下</strong></td><td>震（<strong>动</strong>）</td><td>巽（<strong>入</strong>）</td></tr><tr><td>异类爻在<strong>中</strong></td><td>坎（<strong>陷</strong>）</td><td>离（<strong>丽</strong>）</td></tr><tr><td>异类爻在<strong>上</strong></td><td>艮（<strong>止</strong>）</td><td>兑（<strong>说</strong>）</td></tr></tbody></table><p><strong>「阖户／辟户」的精确化</strong>——《系辞传》说「阖户谓之坤，辟户谓之乾」，讲的是<strong>状态</strong>；麻衣回到卦画，找到了<strong>过程</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>阖户（关门）= 坤象</span></span>
<span class="line"><span>  → 不只是坤卦本身</span></span>
<span class="line"><span>  → 姤卦初爻（一阴生于下）= 阴气刚刚闭合的那一刻</span></span>
<span class="line"><span></span></span>
<span class="line"><span>辟户（开门）= 乾象</span></span>
<span class="line"><span>  → 不只是乾卦本身</span></span>
<span class="line"><span>  → 复卦初爻（一阳生于下）= 阳气刚刚开启的那一刻</span></span></code></pre></div><p><strong>过程比状态更精确，更有信息量</strong>——这正是第六章「辞外见意」的具体实践。</p><p><strong>为什么「入」比「顺」更精确描述巽？</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>坤 = 顺（三爻皆阴，完全顺从）= 静态的承载</span></span>
<span class="line"><span>巽 = 入（一阴在二阳下，从下渗入）= 动态的渗透</span></span></code></pre></div><p>「入」比「顺」多了一个<strong>方向感</strong>：阴气从下方渗入阳气之中——这是<strong>风的运动方式</strong>，不是地的运动方式。</p><h2 id="怎么读" tabindex="-1">怎么读 <a class="header-anchor" href="#怎么读" aria-label="Permalink to &quot;怎么读&quot;">​</a></h2><ol><li>先把八个字的<strong>卦画定义</strong>背下来（不是背「乾＝健」，而是背「三画皆奇＝健」）；</li><li>再看它们如何推广到六十四卦（凡含此结构者皆有其象）；</li><li>最后读「阖户／辟户」——<strong>这一步是示范，不是知识。</strong></li></ol><h2 id="核心内容要点" tabindex="-1">核心内容要点 <a class="header-anchor" href="#核心内容要点" aria-label="Permalink to &quot;核心内容要点&quot;">​</a></h2><ul><li><strong>非特训释</strong>：八字是结构原则，不是专属标签。</li><li><strong>卦画定义</strong>：八字各有精确的爻位结构。</li><li><strong>多见于画象</strong>：一切从卦画之象求取。</li><li><strong>阖户＝姤初</strong>：阴气刚闭的那一刻。</li><li><strong>辟户＝复初</strong>：阳气刚开的那一刻。</li></ul><h2 id="【原典层】原文" tabindex="-1">【原典层】原文 <a class="header-anchor" href="#【原典层】原文" aria-label="Permalink to &quot;【原典层】原文&quot;">​</a></h2>`,22)),e(i,{colophon:"健顺动入 · 陷丽止说 · 当求画象 · 阖辟在初爻",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"正易心法第十二章原文",sections:o,glossary:r}),t[1]||(t[1]=n("blockquote",null,[n("p",null,"注：本页依所据底本录入。原文「当求之于画象」的「画象」、以及末句引《系辞传》「阖户谓之坤，辟户谓之乾」皆随底本，不作统一。")],-1)),t[2]||(t[2]=n("h2",{id:"【原典层】字词释义",tabindex:"-1"},[h("【原典层】字词释义 "),n("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),e(l,{items:[{term:"八字非专属",pinyin:["bā","zì"],meaning:"健顺动入陷丽止说不是八卦的专属标签，而是「三画皆奇／一阳在二阴下」这类结构的通用描述原则。"},{term:"当求之于画象",pinyin:["huà","xiàng"],meaning:"八字的本义要从卦画结构中求取，而非死记标签——这是对第四章「只作八字说」的正面回应。"},{term:"入 与 顺",pinyin:["rù","shùn"],meaning:"坤为顺（静态承载），巽为入（动态渗透）。「入」多了一个方向感：阴气从下方渗入阳气之中，如风。"},{term:"阖户（姤初）",pinyin:["hé","hù"],meaning:"《系辞》「阖户谓之坤」讲的是状态（坤）；麻衣回到卦画，找到过程——阴气刚闭的那一刻即姤卦初爻。"},{term:"辟户（复初）",pinyin:["pì","hù"],meaning:"《系辞》「辟户谓之乾」；麻衣指复卦初爻——阳气刚开的那一刻（冬至一阳来复）。"}]}),t[3]||(t[3]=s(`<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一章在说什么" tabindex="-1">象：这一章在说什么 <a class="header-anchor" href="#象-这一章在说什么" aria-label="Permalink to &quot;象：这一章在说什么&quot;">​</a></h3><p>本章是<strong>方法论的完整示范</strong>：八字不是标签，是结构原则；这个原则可以推广到所有卦爻。</p><p><strong>核心命题</strong>：八卦的八个义理标签，不是八卦的专属名称，而是<strong>卦画结构的通用描述原则</strong>——凡六十四卦中出现相同结构，就适用相同的义理。</p><h3 id="理-为什么这样说" tabindex="-1">理：为什么这样说 <a class="header-anchor" href="#理-为什么这样说" aria-label="Permalink to &quot;理：为什么这样说&quot;">​</a></h3><p><strong>这是对第四章「只作八字说」的正面回应</strong>：</p><table tabindex="0"><thead><tr><th></th><th>做法</th></tr></thead><tbody><tr><td>错误（汉儒）</td><td>乾＝健，背下来；把八字当标签贴纸</td></tr><tr><td>正确（麻衣）</td><td>「健」= 三画皆奇的卦画结构；凡见三画皆奇，就有「健」象</td></tr></tbody></table><p><strong>从名词（标签）到动词（结构原则）的转变</strong>——不是「乾叫做健」，而是「三画皆奇的结构，就是健的运作方式」。</p><p><strong>「阖户／辟户」的示范意义</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第一步：找到《系辞传》的一个命题（阖户谓之坤，辟户谓之乾）</span></span>
<span class="line"><span>第二步：不满足于文字理解</span></span>
<span class="line"><span>第三步：回到卦画，找到最精确的对应（阖户→姤初爻，辟户→复初爻）</span></span>
<span class="line"><span>第四步：得到更深的理解——过程比状态更有信息量</span></span></code></pre></div><p><strong>这正是第六章「辞外见意」的具体实践。</strong></p><h3 id="用-今天怎么进入这一章" tabindex="-1">用：今天怎么进入这一章 <a class="header-anchor" href="#用-今天怎么进入这一章" aria-label="Permalink to &quot;用：今天怎么进入这一章&quot;">​</a></h3><ul><li>把八个字改写成<strong>结构公式</strong>（「三画皆奇＝健」「一阳在二阴下＝动」），背公式而不背标签；</li><li>拿手边的任意一卦试一次：<strong>它的某个局部结构，对应八字中的哪一个？</strong></li><li>记住：<strong>答案是有限的，方法是无限的。</strong></li></ul><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>健、顺、动、入、陷、丽、止、说——这八个字不只是乾坤六子的训诂标签。</p><p>说「非特训释」，是说不可以只在这八个字上死板套用，应当从卦画中求取真义。</p><p>健：三爻皆奇；顺：三爻皆偶；动：一阳在二阴之下；入：一阴在二阳之下；陷：一阳在二阴之中；丽：一阴在二阳之中；止：一阳在二阴之上；说：一阴在二阳之上。</p><p>凡此所论，都要从卦画之象中去看。</p><p>比如「阖户谓之坤」——姤卦的初爻就是这个象；「辟户谓之乾」——复卦的初爻就是这个象。</p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p><strong>一句话</strong>：第十二章把《说卦传》的八个答案，换成了一个方法——<strong>「震＝动」要背，「一阳在二阴下＝动」只要懂一次，就到处能用。</strong></p></blockquote><p>可以按这几条慢慢写：</p><ul><li><strong>从名词到动词</strong>——这一章最要紧的转变。<strong>标签是贴在事物外面的，结构是从事物本身长出来的。</strong> 我平时学东西，是在收集标签，还是在理解结构？</li><li><strong>「阖户／辟户」那一步</strong>——麻衣不满足于「坤＝关门」，他问：<strong>关门这个动作发生在哪一刻？</strong> 答案：姤初爻。<strong>这就是「找落处」最漂亮的一次示范——把静态的名词，还原成动态的一刻。</strong></li><li><strong>「入」比「顺」多出来的东西</strong>——方向感。<strong>同样是阴，落在下爻就是「入」，落在整体就是「顺」。位置不只是位置，是方向。</strong></li><li><strong>答案有限，方法无限</strong>——这句话可以直接搬去别处：<strong>我是在攒答案，还是在找方法？</strong></li><li><strong>留给自己的问题</strong>（承接昇哥的钩子）：他留的练习是——<strong>大壮卦初爻结构是「三阳在下」，与「健」完全吻合；那么四爻（阳居阴位）呢？它的局部结构是什么？</strong> 我的推法：<strong>四爻若以「三爻一组」的局部看——取二三四爻（阳阳阳）＝三画皆奇＝健；取三四五爻（阳阳阴）＝一阴在二阳上＝说（兑）。</strong> 所以大壮的四爻同时带着「健」与「说」两重义——<strong>看一个爻，不能只看它自己，要看它所在的小结构。</strong> 这大概就是麻衣说「多见于画象」的意思。</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/yijing/zheng-yi-xin-fa/">正易心法总览</a></li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-04">第四章 · 《易》道不传</a> — 「只作八字说」之弊（本章是正面回应）</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-06">第六章 · 消息卦画</a> — 「辞外见意」（阖辟之解即其实践）</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-09">第九章 · 乃生六子</a> — 入位决定卦性（本章给出结构原则）</li><li><a href="/Dao/yijing/shi-yi/shuo-gua-zhuan">说卦传</a> — 「乾，健也……兑，说也」：麻衣给出了这八个字的推导方式</li></ul>`,25))])}}});export{y as __pageData,x as default};
